import { getAdminSession } from "../../../lib/auth";
import { prisma } from "../../../lib/prisma";

function serializeHospital(hospital) {
  return {
    id: hospital.id,
    name: hospital.name,
    city: hospital.city,
    state: hospital.state,
    address: hospital.address,
    pincode: hospital.pincode,
    phone: hospital.phone,
    email: hospital.email,
    website: hospital.website,
    rating: hospital.rating,
    specialties: hospital.specialties,
    isOpen24Hours: hospital.isOpen24Hours,
    doctorCount: hospital._count?.doctors ?? 0,
  };
}

export async function GET() {
  const admin = await getAdminSession();

  if (!admin) {
    return Response.json({ error: "Unauthorized" }, { status: 401 });
  }

  const hospitals = await prisma.hospital.findMany({
    include: {
      _count: {
        select: { doctors: true },
      },
    },
    orderBy: [{ createdAt: "desc" }],
  });

  return Response.json({ hospitals: hospitals.map(serializeHospital) });
}

export async function POST(request) {
  try {
    const admin = await getAdminSession();

    if (!admin) {
      return Response.json({ error: "Unauthorized" }, { status: 401 });
    }

    const body = await request.json();

    const hospital = await prisma.hospital.create({
      data: {
        name: body.name?.trim(),
        city: body.city?.trim(),
        state: body.state?.trim(),
        address: body.address?.trim(),
        pincode: body.pincode?.trim() || null,
        phone: body.phone?.trim(),
        email: body.email?.trim().toLowerCase(),
        website: body.website?.trim() || null,
        rating: Number(body.rating) || 0,
        specialties: Array.isArray(body.specialties) ? body.specialties : [],
        isOpen24Hours: Boolean(body.isOpen24Hours),
      },
      include: {
        _count: {
          select: { doctors: true },
        },
      },
    });

    return Response.json({ hospital: serializeHospital(hospital) }, { status: 201 });
  } catch (error) {
    console.error("Create hospital API error:", error);
    return Response.json(
      { error: "Unable to create hospital right now." },
      { status: 500 }
    );
  }
}
